1	#!/usr/bin/env python3
2	"""ClientBook HTTP service."""
3	import argparse
4	import datetime
5	import json
6	import re
7	import signal
8	import sqlite3
9	from http.server import BaseHTTPRequestHandler, HTTPServer
10	from pathlib import Path
11	from urllib.parse import urlsplit
12	
13	PRODUCT = "ClientBook"
14	RESOURCE = "clients"
15	OPTIONAL_FIELDS = ("source", "region", "industry", "important_date")
16	ALL_COLUMNS = ("name",) + OPTIONAL_FIELDS
17	MAX_BODY = 10 * 1024 * 1024
18	DATE_RE = re.compile(r"^(\d{4})-(\d{2})-(\d{2})$")
19	
20	PAGE = '''<!doctype html>
21	<html lang="zh-CN">
22	<head>
23	<meta charset="utf-8">
24	<meta name="viewport" content="width=device-width,initial-scale=1">
25	<title>ClientBook · 客户联系人与商机记录</title>
26	<style>
27	body{font-family:system-ui,sans-serif;max-width:60rem;margin:3rem auto;padding:0 1rem;line-height:1.7;color:#1c2733}
28	a{color:#175b9c}
29	h1{margin-bottom:.2rem}
