38	.banner{padding:.6rem 1rem;border-radius:6px;margin-bottom:.75rem}
39	.banner.ok{background:#e9f7ec;border:1px solid #bfe3c8}
40	.banner.bad{background:#fdeeee;border:1px solid #f3c4c4}
41	.banner.warn{background:#fdf6e6;border:1px solid #ecd9a8}
42	.banner.busy{background:#eef4fb;border:1px solid #c3d5e8}
43	.failures{border:1px solid #ecd7d7;background:#fdf6f6;border-radius:6px;padding:.5rem 1rem;max-height:16rem;overflow:auto}
44	.failures b{color:#a02b2b}
45	.failures ul{margin:.4rem 0}
46	table{border-collapse:collapse;width:100%}
47	#clients-table{display:none}
