49	#clients-empty{display:none}
50	#clients-empty.on{display:block}
51	#clients-load-error{display:none}
52	#clients-load-error.on{display:block;color:#a06a16}
53	th,td{text-align:left;padding:.45rem .6rem;border-bottom:1px solid #e3e8ee;vertical-align:top}
54	th{font-size:.85rem;color:#5b6b7b;font-weight:600}
55	.muted{color:#9aa7b4}
56	#clients-body tr.selected{background:#f1f6fb}
57	.sel-panel{background:#f5f8fb;border:1px solid #d8dee6;border-radius:6px;padding:.6rem .8rem;margin:.8rem 0}
58	.sel-list{margin-top:.35rem}
59	.sel-chip{display:inline-block;background:#fff;border:1px solid #cdd7e2;border-radius:999px;padding:.1rem .35rem .1rem .6rem;margin:.2rem .35rem .2rem 0;font-size:.9rem;white-space:nowrap}
60	.sel-chip button{border:none;background:none;color:#5b6b7b;font-size:1.05rem;line-height:1;padding:0 .25rem;cursor:pointer}
61	.sel-chip button:hover{color:#a02b2b}
62	.bf{border:1px solid #d8dee6;border-radius:6px;padding:.55rem .8rem;margin:.6rem 0}
63	.bf-head{display:flex;flex-wrap:wrap;gap:.8rem;align-items:center;margin-bottom:.35rem}
64	.bf-head b{min-width:4.5rem}
65	.bf-head label{font-weight:400;white-space:nowrap}
66	.bf textarea{width:100%;box-sizing:border-box;font:inherit;resize:vertical;padding:.3rem .45rem}
67	.bf input[type=text]{font:inherit;padding:.3rem .45rem}
68	.bf textarea:disabled,.bf input:disabled{background:#f2f4f7;color:#8a97a5}
69	.bf .val-hint{margin:.25rem 0 0;font-size:.85rem;color:#5b6b7b}
70	#batch-report{margin-top:.75rem}
71	.footer{color:#5b6b7b;font-size:.9rem;margin-top:2rem}
72	</style>
73	</head>
74	<body>
75	<main>
76	<h1>ClientBook</h1>
77	<p class="subtitle">客户联系人与商机记录</p>
78	
79	<section class="card">
80	<h2>从 CSV 导入客户</h2>
81	<form id="import-form">
82	  <!-- 不使用原生 required 拦截：未选文件时由提交处理统一在页内提示先选择 CSV，
83	       与批量修改表单的自定义校验提示口径一致，避免原生气泡拦截后页内无提示。 -->
84	  <input type="file" id="file-input" accept=".csv,text/csv,text/plain">
85	  <span class="filename" id="filename"></span>
86	  <div style="margin-top:.75rem"><button type="submit" id="submit-btn">导入</button></div>
87	</form>
88	<p class="hint">表头须包含 name（必需），可选 source、region、industry、important_date，顺序不限；重要日期须为 YYYY-MM-DD 真实日期。支持带引号字段与字段内换行（UTF-8，可带 BOM）。</p>
89	<div id="report"></div>
90	</section>
91	
92	<h2>客户列表</h2>
93	<p id="clients-empty" class="muted">还没有客户记录。</p>
94	<p id="clients-load-error" class="muted"></p>
95	<table id="clients-table">
96	  <thead><tr><th style="width:2.2rem"><input type="checkbox" id="check-all" title="全选/取消全选当前列表"></th><th>编号</th><th>客户名称</th><th>来源</th><th>地区</th><th>行业</th><th>重要日期</th></tr></thead>
97	  <tbody id="clients-body"></tbody>
98	</table>
99	
100	<section class="card" id="batch-card">
101	<h2>批量修改选中客户</h2>
102	<div class="sel-panel">
103	  已选择 <b id="sel-count">0</b> 名客户：
104	  <div class="sel-list" id="sel-list"><span class="muted" id="sel-none">尚未勾选任何客户，勾选列表中的客户后可批量修改。</span></div>
105	</div>
106	<form id="batch-form">
107	  <div id="batch-fields"></div>
108	  <p class="hint">每个字段可分别选择「保持原值」「设为填写的值」或「清空」；初次进入编辑时全部保持原值，留空不会清空资料。来源、地区和行业保留内部空白与换行，仅含空白的填写值按清空处理；重要日期须为 YYYY-MM-DD 真实日历日期。客户名称和编号不参与编辑，也不会新建客户。</p>
109	  <div style="margin-top:.6rem">
110	    <button type="submit" id="batch-submit" disabled>保存修改</button>
111	  </div>
112	</form>
113	<div id="batch-report"></div>
114	</section>
115	
116	<p class="footer"><a href="/api/clients">查看客户列表接口</a> · <a href="/health">服务状态</a></p>
117	</main>
118	<script>
119	const ESC = {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"};
120	const esc = s => String(s === null || s === undefined ? "" : s).replace(/[&<>"']/g, c => ESC[c]);
121	const blank = v => (v === null || v === undefined || v === "") ? '<span class="muted">—</span>' : esc(v);
122	
123	const BATCH_FIELDS = [
124	  {key: "source", label: "来源"},
125	  {key: "region", label: "地区"},
126	  {key: "industry", label: "行业"},
127	  {key: "important_date", label: "重要日期", date: true},
128	];
129	
130	let clients = [];
131	const selected = new Set();
132	// 一次批量保存从发出到本次结果处理结束期间为 true：期间只能有这一次请求，
133	// 勾选变化与表单重复提交都不能解除或新增请求。
134	let batchSaving = false;
135	// 一次 CSV 导入从提交文件开始，到回复读取、结果展示以及该结果需要的客户列表
136	// 刷新全部结束期间为 true：期间只能有最初发出的那一次导入请求；重复点击、
137	// 回车等再次触发表单提交都直接忽略，不解除等待、不新增请求、不更换提示。
138	let importing = false;
139	// 客户列表读取的发起序号，只增不减：同一页面可能同时有多次读取在途
140	// （首次打开、导入成功后、批量保存成功后都会各自发起一次）。先后以读取
141	// 发起的时间为准，而不是回复到达的时间：只有序号仍等于当前最新值的读取
142	// （即最近发起的那次）才能决定表格内容与读取提示；较早发起的读取无论
143	// 成功、失败还是空列表、无论回复何时到达，都不再影响页面——不能覆盖
144	// 更新读取已经显示的客户资料，不能新增读取失败或列表暂未更新的提示，
145	// 也不能撤掉更新读取已经给出的提示或换掉它保留的表格。
146	let loadSeq = 0;
147	
148	// 客户编号最大可到 9223372036854775807（2^63-1），超出 JS 安全整数范围：
149	// 直接 JSON.parse 会把 9007199254740993 这样的大编号舍入成相近数值，两个
150	// 不同客户可能显示成同一编号。这里在解析前把超出安全范围的整数字面量原样
151	// 包成字符串（逐字符扫描，跳过字符串内容，只处理结构中的数字），解析后
152	// 编号一律以精确十进制文本保存、显示与比较；提交批量修改时再原样拼回
153	// JSON 整数——接口上的编号仍是 JSON 整数，不改成文本编号。
154	function quoteUnsafeIntTokens(jsonText) {
155	  let out = "";
156	  let i = 0;
157	  const n = jsonText.length;
158	  let inString = false;
159	  while (i < n) {
160	    const c = jsonText[i];
161	    if (inString) {
162	      out += c;
163	      if (c === "\\\\" && i + 1 < n) {
164	        out += jsonText[i + 1];
165	        i += 2;
166	        continue;
167	      }
168	      if (c === '"') inString = false;
169	      i += 1;
170	      continue;
171	    }
172	    if (c === '"') {
173	      inString = true;
174	      out += c;
175	      i += 1;
176	      continue;
177	    }
178	    if (c === "-" || (c >= "0" && c <= "9")) {
179	      let j = i + 1;
180	      while (j < n && /[0-9.eE+-]/.test(jsonText[j])) j += 1;
181	      const token = jsonText.slice(i, j);
182	      // 只处理纯整数字面量；超出安全整数范围（含恰好 2^53）的包成字符串，
183	      // 保留原始数字文本，安全范围内的保持原样由 JSON.parse 解析成数字。
184	      if (/^-?\d+$/.test(token) && !Number.isSafeInteger(Number(token))) {
185	        out += '"' + token + '"';
186	      } else {
187	        out += token;
188	      }
189	      i = j;
190	      continue;
191	    }
192	    out += c;
193	    i += 1;
194	  }
195	  return out;
196	}
197	
198	// 编号在页面内统一为精确十进制文本（安全范围内的数字由 String 转换结果精确，
199	// 更大的一开始就是原文字符串），比较、查找、显示都用它。
200	function clientIdText(id) {
201	  return typeof id === "string" ? id : String(id);
202	}
203	
204	// 正整数十进制文本（无前导零）的数值序：先比位数，位数相同按字典序。
205	function compareClientIds(a, b) {
206	  if (a.length !== b.length) return a.length - b.length;
207	  return a < b ? -1 : a > b ? 1 : 0;
208	}
209	
210	function syncSubmitState() {
211	  const btn = document.getElementById("batch-submit");
212	  btn.disabled = batchSaving || selected.size === 0;
213	  btn.textContent = batchSaving ? "正在保存…" : "保存修改";
214	}
215	
216	function syncImportState() {
217	  const btn = document.getElementById("submit-btn");
218	  btn.disabled = importing;
219	  btn.textContent = importing ? "正在导入…" : "导入";
220	}
221	
222	async function loadClients() {
223	  // 只在明确读到有效客户列表（真正的空列表也算）时才更新页面；
224	  // 连接错误、非成功状态、响应无法解析或未包含 clients 数组都视为读取失败：
225	  // 保留此前已显示的客户编号、名称与各字段内容，不清空表格、不显示空列表提示。
226	  // 返回 "updated"（本次是最近发起的读取且已更新页面）或 "stale"（已有更新的
227	  // 读取发起，本次结果不再影响页面）；最近发起的读取失败时抛错，由调用方
228	  // 补充各自场景的提示。
229	  const seq = ++loadSeq;
230	  const stale = () => seq !== loadSeq;
231	  const note = document.getElementById("clients-load-error");
232	  let list;
233	  try {
234	    const res = await fetch("/api/clients");
235	    if (!res.ok) throw new Error("服务返回非成功状态（HTTP " + res.status + "）");
236	    // 先取原文再解析：大编号超出 JS 安全整数范围，须把这类整数字面量包成
237	    // 字符串后再 JSON.parse，否则两个不同客户可能被舍入成同一编号。
238	    const raw = await res.text();
239	    const data = JSON.parse(quoteUnsafeIntTokens(raw));
240	    if (!data || !Array.isArray(data.clients)) {
241	      throw new Error("响应未包含有效的客户列表");
242	    }
243	    list = data.clients.map(r => ({...r, id: clientIdText(r.id)}));
244	  } catch (err) {
245	    // 已有更新的读取发起：本次旧回复（包括连接错误、非成功状态、无法解析）
246	    // 不再影响页面，不新增读取失败提示，也不动表格与勾选。
247	    if (stale()) return "stale";
248	    let message = err.message;
249	    if (err instanceof SyntaxError) message = "响应无法解析为有效数据";
250	    if (err instanceof TypeError) message = "无法连接到服务（网络错误）";
251	    note.textContent = "客户列表读取失败：" + message +
252	      "，当前显示的资料可能不是最新内容；保存结果不受影响，稍后刷新页面即可重新读取。";
253	    note.classList.add("on");
254	    // 读取失败期间不能让表格或“还没有客户记录”冒充真实的空列表；
255	    // 此前已渲染的行保留不动，之后真正读到空列表时再由 renderClients 恢复空状态提示。
256	    document.getElementById("clients-empty").classList.remove("on");
257	    throw new Error(message);
258	  }
259	  // 等待回复期间已有更新的读取发起：本次旧列表（即使真实、即使是空列表）
260	  // 不能抢先决定页面内容，客户行、读取提示、现有勾选与已选客户说明都保持不动。
261	  if (stale()) return "stale";
262	  note.classList.remove("on");
263	  note.textContent = "";
264	  clients = list;
265	  const known = new Set(clients.map(r => r.id));
266	  for (const id of [...selected]) {
267	    if (!known.has(id)) selected.delete(id);
268	  }
269	  renderClients();
270	  renderSelection();
271	  return "updated";
272	}
273	
274	function renderClients() {
275	  const tbl = document.getElementById("clients-table");
276	  const empty = document.getElementById("clients-empty");
277	  const body = document.getElementById("clients-body");
278	  if (clients.length) {
279	    tbl.classList.add("on");
280	    empty.classList.remove("on");
281	    body.innerHTML = clients.map(r =>
282	      '<tr data-id="' + esc(r.id) + '"' + (selected.has(r.id) ? ' class="selected"' : "") + ">" +
283	      '<td><input type="checkbox" class="row-check" value="' + esc(r.id) + '"' +
284	      (selected.has(r.id) ? " checked" : "") + " aria-label='选择客户 " + esc(r.id) + "'></td>" +
285	      "<td>" + esc(r.id) + "</td><td>" + esc(r.name) + "</td><td>" + blank(r.source) +
286	      "</td><td>" + blank(r.region) + "</td><td>" + blank(r.industry) +
287	      "</td><td>" + blank(r.important_date) + "</td></tr>").join("");
288	  } else {
289	    tbl.classList.remove("on");
290	    empty.classList.add("on");
291	    body.innerHTML = "";
292	  }
293	  syncCheckAll();
294	}
295	
296	function syncCheckAll() {
297	  const box = document.getElementById("check-all");
298	  box.checked = clients.length > 0 && selected.size === clients.length;
299	  box.indeterminate = selected.size > 0 && selected.size < clients.length;
300	}
301	
302	function renderSelection() {
303	  document.getElementById("sel-count").textContent = String(selected.size);
304	  const list = document.getElementById("sel-list");
305	  if (!selected.size) {
306	    list.innerHTML = '<span class="muted">尚未勾选任何客户，勾选列表中的客户后可批量修改。</span>';
307	  } else {
308	    const byId = new Map(clients.map(r => [r.id, r]));
309	    list.innerHTML = [...selected].sort(compareClientIds).map(id => {
310	      const r = byId.get(id);
311	      return '<span class="sel-chip">#' + esc(id) + " " + esc(r ? r.name : "") +
312	        ' <button type="button" data-remove="' + esc(id) + '" title="取消勾选该客户">×</button></span>';
313	    }).join("");
314	  }
315	  syncSubmitState();
316	  document.querySelectorAll("#clients-body tr").forEach(tr => {
317	    tr.classList.toggle("selected", selected.has(tr.dataset.id));
318	  });
319	  syncCheckAll();
320	}
321	
322	function buildBatchFields() {
323	  const wrap = document.getElementById("batch-fields");
324	  wrap.innerHTML = BATCH_FIELDS.map(f =>
325	    '<div class="bf" data-field="' + f.key + '">' +
326	      '<div class="bf-head"><b>' + f.label + "</b>" +
327	        '<label><input type="radio" name="' + f.key + '-op" value="keep" checked> 保持原值</label>' +
328	        '<label><input type="radio" name="' + f.key + '-op" value="set"> 设为填写的值</label>' +
329	        '<label><input type="radio" name="' + f.key + '-op" value="clear"> 清空</label>' +
330	      "</div>" +
331	      (f.date
332	        ? '<input type="text" class="bf-value" disabled placeholder="YYYY-MM-DD" autocomplete="off">'
333	        : '<textarea class="bf-value" rows="2" disabled></textarea>') +
334	      '<p class="val-hint">' + (f.date
335	        ? "非空时须为 YYYY-MM-DD 真实日历日期；仅含空白的填写值按清空处理。"
336	        : "去除前后空白后保存，内部空白与换行保留；仅含空白的填写值按清空处理。") +
337	      "</p></div>").join("");
338	  wrap.querySelectorAll(".bf").forEach(card => {
339	    const input = card.querySelector(".bf-value");
340	    card.querySelectorAll('input[type=radio]').forEach(radio => radio.addEventListener("change", () => {
341	      const op = card.querySelector('input[type=radio]:checked').value;
342	      input.disabled = op !== "set";
343	      if (op === "set") input.focus();
344	    }));
345	  });
346	}
347	
348	function collectBatchPayload() {
349	  const updates = {};
350	  for (const card of document.querySelectorAll("#batch-fields .bf")) {
351	    const key = card.dataset.field;
352	    const op = card.querySelector('input[type=radio]:checked').value;
353	    if (op === "keep") {
354	      updates[key] = {op: "keep"};
355	    } else if (op === "clear") {
356	      updates[key] = {op: "clear"};
357	    } else {
358	      updates[key] = {op: "set", value: card.querySelector(".bf-value").value};
359	    }
360	  }
361	  // 安全范围内的编号恢复为 JSON 数字，超出安全范围的保留精确十进制文本，
362	  // 由 batchPayloadJson 原样拼成 JSON 整数（不经过 Number，不会丢精度）。
363	  const ids = [...selected].sort(compareClientIds).map(id => {
364	    const n = Number(id);
365	    return Number.isSafeInteger(n) ? n : id;
366	  });
367	  return {ids, updates};
368	}
369	
370	// ids 是精确十进制文本（可能超出 JS 安全整数范围），不能经 Number 再
371	// JSON.stringify（会丢精度或直接被拒）；编号只含数字，原样拼接即得到
372	// 接口要求的 JSON 整数数组，updates 仍按普通 JSON 序列化。
373	function batchPayloadJson(payload) {
374	  return '{"ids":[' + payload.ids.join(",") + '],"updates":' +
375	    JSON.stringify(payload.updates) + "}";
376	}
377	
378	function resetBatchForm() {
379	  document.querySelectorAll("#batch-fields .bf").forEach(card => {
380	    card.querySelector('input[value=keep]').checked = true;
381	    const input = card.querySelector(".bf-value");
382	    input.value = "";
383	    input.disabled = true;
