817	def _normalize_set_value(field_name, value):
818	    """校验 set 操作的值并返回最终入库值；非法时抛 BatchUpdateError。
819	
820	    去除前后空白；仅含空白按清空（None）处理；来源/地区/行业保留内部空白与换行；
821	    重要日期非空时须为 YYYY-MM-DD 真实日历日期。
822	    """
823	    if not isinstance(value, str):
824	        raise BatchUpdateError("%s的设置值不是文本" % FIELD_LABELS[field_name])
825	    text = value.strip()
826	    if not text:
827	        return None
828	    if field_name == "important_date":
829	        ok, reason = check_date(text)
830	        if not ok:
831	            raise BatchUpdateError(reason)
832	    return text
