925	def parse_csv(text):
926	    """解析 RFC 4180 风格 CSV，返回 (header, data_rows)。
927	
928	    支持引号包裹的字段、引号内逗号与换行、双引号转义；
929	    引号外支持 LF / CRLF / CR 换行。结构损坏时抛 FileError：
930	    - 未加引号的字段中出现双引号（双引号只能在字段开头用于包住整个字段）；
931	    - 结束引号后出现逗号、换行或文件结束以外的字符（含空格）；
932	    - 文件结束时仍有字段处于引号内（引号未闭合）。
933	    错误信息区分上述三种情况，并指出发生在表头还是第 N 条数据记录
934	    （数据记录编号不包含表头，引号字段内的换行不增加编号）。
935	    """
936	    rows = []
937	    record = []
938	    field = []
939	    quoted = False        # 当前字段处于引号内
940	    started = False       # 当前字段已经开始（已有内容或已进入引号）
941	    closed = False       # 引号字段刚结束，等待逗号 / 换行 / 文件结束
942	    record_number = 0     # 0 = 表头，1 起为数据记录
943	    i = 0
944	    n = len(text)
945	
946	    def location():
947	        return "表头" if record_number == 0 else "第 %d 条数据记录" % record_number
948	
949	    def structure_error(kind):
950	        raise FileError("CSV 结构损坏（%s）：%s" % (location(), kind))
951	
952	    def finish_record():
953	        nonlocal record, field, started, closed
954	        record.append("".join(field))
955	        rows.append(record)
956	        record = []
957	        field = []
958	        started = False
959	        closed = False
960	
961	    while i < n:
962	        c = text[i]
963	        if quoted:
964	            if c == '"':
965	                if i + 1 < n and text[i + 1] == '"':
966	                    field.append('"')
967	                    i += 2
968	                    continue
969	                quoted = False
970	                closed = True
971	                i += 1
972	                continue
973	            if c == "\r":
974	                # 统一字段内换行符为 LF
975	                if i + 1 < n and text[i + 1] == "\n":
976	                    i += 1
977	                field.append("\n")
978	                i += 1
979	                continue
980	            field.append(c)
981	            i += 1
982	            continue
983	        if closed:
984	            # 引号已结束，只允许逗号、记录换行或文件结束
985	            if c == ",":
986	                record.append("".join(field))
987	                field = []
988	                started = False
989	                closed = False
990	            elif c in "\r\n":
991	                if c == "\r" and i + 1 < n and text[i + 1] == "\n":
992	                    i += 1
993	                finish_record()
994	                record_number += 1
995	            else:
996	                structure_error("结束引号后有多余字符，结束引号后只能紧接逗号、记录换行或文件结束")
997	            i += 1
998	            continue
999	        if c == '"' and not started:
1000	            quoted = True
1001	            started = True
1002	        elif c == '"':
1003	            structure_error("未加引号的字段中出现双引号，双引号只能在字段开头用于包住整个字段")
1004	        elif c == ",":
1005	            record.append("".join(field))
1006	            field = []
1007	            started = False
1008	        elif c in "\r\n":
1009	            if c == "\r" and i + 1 < n and text[i + 1] == "\n":
1010	                i += 1
1011	            if not started and not record and not field:
1012	                # 空白行：不作为数据记录（显式的 "" 空字段 started=True，仍会保留）
1013	                i += 1
1014	                continue
1015	            finish_record()
1016	            record_number += 1
1017	        else:
1018	            field.append(c)
1019	            started = True
1020	        i += 1
1021	    if quoted:
1022	        structure_error("引号未闭合，文件结束时仍有字段处于引号内")
1023	    if started or field or record or closed:
1024	        record.append("".join(field))
1025	        rows.append(record)
1026	    if not rows:
1027	        raise FileError("CSV 内容为空：缺少表头")
1028	    return rows[0], rows[1:]
