1031	def check_date(value):
1032	    """校验 YYYY-MM-DD 且为真实日历日期，返回 (是否合法, 错误原因)。"""
1033	    match = DATE_RE.match(value)
1034	    if not match:
1035	        return False, "重要日期格式无效（%s）：须为 YYYY-MM-DD" % value
1036	    try:
1037	        datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
1038	    except ValueError:
1039	        return False, "重要日期无效（%s）：不是真实日历日期" % value
1040	    return True, None
