1089	            if date_value:
1090	                ok, reason = check_date(date_value)
1091	                if not ok:
1092	                    problems.append(reason)
1093	        if problems:
1094	            failures.append({"row": row_number, "reason": "；".join(problems)})
1095	            continue
1096	
1097	        key = name.casefold()
1098	        if key in existing:
1099	            failures.append({
1100	                "row": row_number,
