// 页面源码经 esc() 转义了 & < > " '（属性场景也安全）；但读 innerHTML 时
// 浏览器按片段序列化规则只在文本节点中转义 & < >，引号在文本中没有特殊含义、
// 会原样返回。因此与 innerHTML 比对时使用这个「序列化后」的期望，
// 引号是否被转义由文字完整显示与结构审计间接保证。
const escHtml = s => String(s).replace(/[&<>]/g,
  c => ({"&": "&amp;", "<": "&lt;", ">": "&gt;"}[c]));
const DASH_HTML = '<span class="muted">—</span>';

